from h import *
O=[]
O.append(R(6553525,
ar=("سلطة الدجاج واللفت الأخضر (كيل) مع صلصة الزنجبيل الطازج","هذه السلطة السريعة والسهلة جاهزة في لحظات بمكونات قليلة فقط، وهي مثالية لوجبة غداء متوازنة وسريعة أو طبق جانبي.","4","2 كوب سلطة + 3 أونصات دجاج مطبوخ + 3 ملاعق كبيرة صلصة",
["1 رطل صدور دجاج بدون عظم وبدون جلد","8 كوب خضروات ورقية مشكلة (سبانخ مكبوسة مع أوراق كيل صغيرة)","¾ كوب صلصة سلطة خفيفة بالتوت الأحمر","2 ملعقة صغيرة زنجبيل طازج (مبشور)"],
["سخّن شواية أو مقلاة شواء على حرارة متوسطة عالية. ادهن الدجاج ببخاخ الطهي، ورشّ عليه ¼ ملعقة صغيرة من الملح و¼ ملعقة صغيرة من الفلفل إن رغبت. اطهِه 6 دقائق من كل جانب أو حتى يزول اللون الوردي من وسطه. اتركه يبرد ثم قطّعه إلى شرائح رفيعة.","وزّع كميات متساوية من الخضروات الورقية والدجاج على أربعة أطباق عشاء. اخفق صلصة السلطة والزنجبيل حتى يمتزجا جيدًا. اسكب كميات متساوية منها فوق الأطباق."],[],[])))
O.append(R(6553785,
ar=("كونجي الشوفان","هذه النسخة من عصيدة تقليدية عالية الكربوهيدرات من السهل تحضيرها بالحبوب الكاملة وبشكل صحي.","4","¾ كوب عصيدة + 1 بيضة + 1½ ملعقة صغيرة بصل أخضر وكزبرة خضراء",
["1 كوب شوفان مجروش تقليدي","4 كوب مرق خضار قليل الصوديوم","1 ملعقة كبيرة صلصة صويا مخفضة الصوديوم","1 كوب فطر أبيض (شامبينيون) (مقطع إلى شرائح)","1 ملعقة كبيرة عصير ليمون أخضر","1 بخّة (0.25 غرام) بخاخ طهي غير لاصق","4 بيضات كبيرة","2 ساق بصل أخضر (مقطعة إلى شرائح)","1 ملعقة كبيرة كزبرة خضراء (مفرومة ناعمًا)"],
["ضع الشوفان والمرق وصلصة الصويا في قدر على نار عالية. اتركه حتى يغلي، ثم اخفض الحرارة ليغلي ببطء حتى يصبح الشوفان طريًا، حوالي 10 دقائق.","ادهن مقلاة تسوية صغيرة غير لاصقة ببخاخ الطهي. أضف الفطر وسوّطه حتى يلين ويتبخر كل السائل، حوالي 4 دقائق. أضف عصير الليمون الأخضر وسوّط حتى يتبخر السائل. أضف الفطر إلى عصيدة الشوفان وقلّب.","نظّف مقلاة التسوية، ثم أضف بخاخ الطهي. اقلِ البيض حتى تتماسك الصفار بالكاد.","في وعاء، اسكب ¾ كوب من عصيدة الشوفان، وضع فوقها بيضة مقلية و1½ ملعقة صغيرة من البصل الأخضر والكزبرة الخضراء. كرر ذلك مع الأوعية الثلاثة المتبقية."],[],[])))
O.append(R(6554653,
es=("Papas caseras de camote","Ya sea que las sirva en el desayuno, el almuerzo o la cena, las papas caseras de camote siempre son las favoritas de la familia. Con especias tentadoras, esta es una receta que querrá guardar para preparar una y otra vez.","6","1/2 taza",
["2 cucharadas de aceite de oliva","2 camotes grandes (pelados y cortados en cubos pequeños)","1 cucharadita de pimentón ahumado","1/2 cucharadita de ajo en polvo","1/2 cucharadita de cebolla en polvo","1/2 cucharadita de sal","1/4 de cucharadita de pimienta negra"],
["En una sartén grande, caliente el aceite de oliva a fuego medio.","Agregue los camotes en cubos a la sartén, extendiéndolos en una sola capa.","Saltee los camotes de 15 a 20 minutos, revolviendo de vez en cuando, hasta que estén tiernos por dentro y crujientes por fuera.","Espolvoree el pimentón ahumado, el ajo en polvo, la cebolla en polvo, la sal y la pimienta negra sobre los camotes. Mezcle para cubrirlos de manera uniforme.","Cocine 5 minutos más, para que las especias se integren con los camotes.","Retire la sartén del fuego.","Decore con perejil fresco picado, si lo desea."],[],[]),
ar=("بطاطا حلوة مقلية منزلية","سواء قدّمتها في الفطور أو الغداء أو العشاء، فإن البطاطا الحلوة المقلية المنزلية هي دائمًا المفضلة لدى العائلة. بتوابلها المثيرة للشهية، هذه وصفة ستحرص على حفظها لتحضيرها مرارًا وتكرارًا.","6","½ كوب",
["2 ملعقة كبيرة زيت زيتون","2 حبة بطاطا حلوة كبيرة (مقشرة ومقطعة إلى مكعبات صغيرة)","1 ملعقة صغيرة بابريكا مدخنة","½ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود"],
["في مقلاة كبيرة، سخّن زيت الزيتون على حرارة متوسطة.","أضف مكعبات البطاطا الحلوة إلى المقلاة وافردها في طبقة واحدة.","سوّط البطاطا الحلوة لمدة 15-20 دقيقة مع التحريك من حين لآخر، حتى تصبح طرية من الداخل ومقرمشة من الخارج.","رشّ البابريكا المدخنة ومسحوق الثوم ومسحوق البصل والملح والفلفل الأسود فوق البطاطا الحلوة. قلّب لتتغطى بالتساوي.","اطهِ لمدة 5 دقائق إضافية لتمتزج التوابل مع البطاطا الحلوة.","ارفع المقلاة عن النار.","زيّنها بالبقدونس الطازج المفروم إن رغبت."],[],[])))
O.append(R(6555967,
es=("Lentejas con tomate y coco al curry sobre arroz de coliflor","Estas lentejas con tomate y coco al curry, perfectamente sazonadas, son un plato vegetariano que además es una opción nutritiva y apta para personas con diabetes.","4","3/4 de taza + 1 taza de arroz de coliflor",
["1 cucharadita de aceite de oliva","1 cebolla amarilla mediana (picada fina)","3 dientes de ajo (picados)","1 cucharada de jengibre fresco (rallado)","2 cucharadas de curry en polvo","1 cucharadita de comino molido","1 cucharadita de cilantro molido","1/2 cucharadita de cúrcuma","1/4 de cucharadita de pimienta de cayena","1/4 de cucharadita de sal","1 taza de lentejas (verdes o marrones, secas, enjuagadas)","1 lata (de 14 oz) de tomates en cubos (bajos en sodio)","½ lata (de 14 oz) de leche de coco light","4 tazas de arroz de coliflor congelado (cocido al vapor)","2 cucharadas de perejil fresco (o cilantro, picado)"],
["En una olla grande, caliente el aceite de oliva a fuego medio. Agregue la cebolla picada y saltee hasta que esté transparente, unos 5 minutos.","Agregue el ajo picado y el jengibre rallado a la olla. Saltee 2 minutos más hasta que desprendan aroma.","Agregue el curry en polvo, el comino molido, el cilantro molido, la cúrcuma y la pimienta de cayena. Cocine las especias con la mezcla de cebolla de 1 a 2 minutos.","Agregue a la olla las lentejas enjuagadas, los tomates en cubos y la leche de coco. Revuelva bien para combinar.","Lleve la mezcla a ebullición y luego reduzca el fuego a bajo. Tape la olla y cocine a fuego lento de 20 a 25 minutos, o hasta que las lentejas estén tiernas.","Sirva sobre el arroz de coliflor cocido al vapor y decore con perejil o cilantro fresco picado, si lo desea."],[],[]),
ar=("عدس بالطماطم وجوز الهند والكاري فوق أرز القرنبيط","هذا العدس بالطماطم وجوز الهند والكاري المتبّل بإتقان طبق نباتي وهو أيضًا خيار مغذٍّ ومناسب لمرضى السكري.","4","¾ كوب + 1 كوب أرز قرنبيط",
["1 ملعقة صغيرة زيت زيتون","1 حبة بصل أصفر متوسطة (مفرومة ناعمًا)","3 فص ثوم (مفروم)","1 ملعقة كبيرة زنجبيل طازج (مبشور)","2 ملعقة كبيرة مسحوق الكاري","1 ملعقة صغيرة كمون مطحون","1 ملعقة صغيرة كزبرة مطحونة","½ ملعقة صغيرة كركم","¼ ملعقة صغيرة فلفل كايين","¼ ملعقة صغيرة ملح","1 كوب عدس (أخضر أو بني، جاف، مشطوف)","1 علبة (14 أونصة) طماطم معلبة مقطعة إلى مكعبات (قليلة الصوديوم)","½ علبة (14 أونصة) حليب جوز الهند خفيف","4 كوب أرز قرنبيط مجمد (مطهو على البخار)","2 ملعقة كبيرة بقدونس طازج (أو كزبرة خضراء، مفروم)"],
["في قدر كبير، سخّن زيت الزيتون على حرارة متوسطة. أضف البصل المفروم وسوّطه حتى يصبح شفافًا، حوالي 5 دقائق.","أضف الثوم المفروم والزنجبيل المبشور إلى القدر. سوّطهما لمدة دقيقتين إضافيتين حتى تفوح رائحتهما.","أضف مسحوق الكاري والكمون المطحون والكزبرة المطحونة والكركم وفلفل الكايين. اطهِ التوابل مع خليط البصل لمدة 1-2 دقيقة.","أضف العدس المشطوف والطماطم المقطعة إلى مكعبات وحليب جوز الهند إلى القدر. قلّب جيدًا ليمتزج.","اترك الخليط حتى يغلي، ثم اخفض الحرارة إلى منخفضة. غطِّ القدر واتركه على نار هادئة لمدة 20-25 دقيقة، أو حتى يصبح العدس طريًا.","قدّمه فوق أرز القرنبيط المطهو على البخار وزيّنه بالبقدونس الطازج المفروم أو الكزبرة الخضراء إن رغبت."],[],[])))
O.append(R(6556196,
es=("Bol de burrito de desayuno vegetariano","Este colorido bol de burrito de desayuno, lleno de verduras, ofrece una variante del clásico al usar quinua integral en lugar de arroz blanco como base. Esta receta puede servirse en el desayuno, el almuerzo o la cena porque es una excelente fuente de fibra, una buena fuente de proteína e incluye verduras sin almidón.","4","1 bol",
["1 taza de quinua (cocida sin sal ni grasa)","1 taza de sustituto de huevo","1 taza de frijoles negros (enjuagados y escurridos)","1 taza de tomates cherry (cortados a la mitad)","1 aguacate mediano (en cubos; opcional: use la mitad para reducir la grasa)","1 taza de espinacas baby (picadas)","1 cucharadita de aceite de oliva","1/2 cucharadita de comino molido","1/2 cucharadita de pimentón ahumado","El jugo de 1 lima entera"],
["Caliente el aceite de oliva en una sartén antiadherente a fuego medio. Agregue las espinacas y saltee hasta que se marchiten (unos 2 minutos).","Bata los huevos con el comino y el pimentón, y luego viértalos en la sartén con las espinacas. Revuelva hasta que estén bien cocidos.","Arme el bol. Divida la quinua cocida, los frijoles negros, los tomates, el aguacate y los huevos revueltos entre 4 bols.","Rocíe con el jugo de lima."],[],[]),
ar=("وعاء بوريتو الفطور النباتي","يقدم وعاء بوريتو الفطور الملوّن هذا، المليء بالخضار، لمسة جديدة على الوصفة الكلاسيكية باستخدام الكينوا الكاملة بدلًا من الأرز الأبيض كقاعدة. يمكن تقديم هذه الوصفة في الفطور أو الغداء أو العشاء لأنها مصدر ممتاز للألياف ومصدر جيد للبروتين وتتضمن خضارًا غير نشوية.","4","1 وعاء",
["1 كوب كينوا (مطبوخة بدون ملح أو دهون)","1 كوب بديل البيض","1 كوب فاصولياء سوداء (مشطوفة ومصفاة)","1 كوب طماطم كرزية (مقطعة إلى نصفين)","1 حبة أفوكادو متوسطة (مقطعة إلى مكعبات، اختياري: استخدم نصفها لتقليل الدهون)","1 كوب سبانخ صغيرة (مفرومة)","1 ملعقة صغيرة زيت زيتون","½ ملعقة صغيرة كمون مطحون","½ ملعقة صغيرة بابريكا مدخنة","عصير 1 حبة ليمون أخضر كاملة"],
["سخّن زيت الزيتون في مقلاة غير لاصقة على حرارة متوسطة. أضف السبانخ وسوّطها حتى تذبل (حوالي دقيقتين).","اخفق البيض مع الكمون والبابريكا، ثم اسكبه في المقلاة مع السبانخ. قلّب حتى ينضج تمامًا.","جهّز الوعاء. وزّع الكينوا المطبوخة والفاصولياء السوداء والطماطم والأفوكادو والبيض المقلّب على 4 أوعية.","رشّ عصير الليمون الأخضر."],[],[])))
O.append(R(6556304,
es=("Lechuga para wraps","Información nutricional de los wraps de lechuga","1","2 hojas de lechuga",["2 hojas de lechuga (enjuagadas)"],[],[],[]),
ar=("خس للف السندويشات","المعلومات الغذائية للفائف الخس","1","ورقتا خس",["2 ورقة خس (مشطوفة)"],[],[],[])))
O.append(R(6556849,
es=("Magdalenas de calabaza y plátano","Comience su mañana con un dulce apto para personas con diabetes con estas magdalenas de calabaza y plátano. Más bajas en carbohidratos que las magdalenas del supermercado, acompáñelas con una taza de café para empezar el día de la mejor manera.\n\nAgregue un frasco de huevo y verduras al microondas o bocaditos de espinacas y huevo para completar su desayuno con verduras y proteína.","12","1 magdalena",
["1 1/2 tazas de harina integral de trigo blanco","1/3 de taza de azúcar morena","1 cucharadita de bicarbonato de sodio","1/2 cucharadita de sal","2 cucharaditas de especias para pastel de calabaza","2 huevos","1 taza de puré de calabaza","3 cucharadas de aceite de canola","1 plátano pequeño (machacado)","1 cucharadita de extracto de vainilla","1/4 de taza de nueces (picadas finas)"],
["Precaliente el horno a 350 grados F y forre un molde para magdalenas con capacillos.","Mezcle la harina, el azúcar, el bicarbonato de sodio, la sal y las especias para pastel de calabaza en un tazón grande.","En un tazón pequeño, mezcle los huevos, el puré de calabaza, el aceite, el plátano y la vainilla.","Vierta los ingredientes líquidos sobre los ingredientes secos y revuelva para combinar. Incorpore las nueces con suavidad.","Reparta la masa en el molde para magdalenas y hornee de 18 a 20 minutos, hasta que un palillo salga limpio."],[],[]),
ar=("مافن القرع والموز","ابدأ صباحك بحلوى مناسبة لمرضى السكري مع مافن القرع والموز هذا. إنه أقل في الكربوهيدرات من المافن الجاهز، قدّمه مع كوب من القهوة لبداية مثالية ليومك.\n\nأضف برطمان البيض والخضار في الميكروويف أو لقيمات السبانخ والبيض لإكمال فطورك بالخضار والبروتين!","12","1 كعكة مافن",
["1½ كوب دقيق القمح الكامل الأبيض","⅓ كوب سكر بني","1 ملعقة صغيرة بيكربونات الصوديوم","½ ملعقة صغيرة ملح","2 ملعقة صغيرة بهارات فطيرة القرع","2 بيضة","1 كوب هريس القرع","3 ملعقة كبيرة زيت الكانولا","1 حبة موز صغيرة (مهروسة)","1 ملعقة صغيرة خلاصة الفانيلا","¼ كوب جوز (مفروم ناعمًا)"],
["سخّن الفرن مسبقًا إلى 350 درجة فهرنهايت (175 درجة مئوية) وبطّن صينية المافن بقوالب ورقية.","اخلط الدقيق والسكر وبيكربونات الصوديوم والملح وبهارات فطيرة القرع في وعاء كبير.","في وعاء صغير، اخلط البيض وهريس القرع والزيت والموز والفانيليا.","اسكب المكونات السائلة فوق المكونات الجافة وقلّب حتى تمتزج. أضف الجوز بالطي برفق.","وزّع العجينة في صينية المافن واخبز لمدة 18-20 دقيقة، حتى يخرج عود الأسنان نظيفًا."],[],[])))
O.append(R(6557494,
es=("Pastel de carne de pavo al estilo suroeste","Una buena forma de añadir cereales integrales a los platos de proteína, como el pastel de carne, las hamburguesas y las albóndigas, es usar avena de cocción rápida en lugar del pan molido habitual. Se ha demostrado que la fibra de la avena ayuda a reducir el colesterol. Complete su plato: para una comida clásica de \"carne con papas\", acompáñelo con puré de papas rojas. Añada una ensalada verde con naranja y aguacate para una comida equilibrada.","8","1 rebanada",
["1 rociada de aceite en aerosol antiadherente de 0.25 gramos","1 1/2 libras de carne molida de pavo magra","1 taza de avena de cocción rápida","1 cebolla amarilla grande (picada fina)","2 huevos grandes (batidos)","1 pimiento morrón verde mediano (en cubos pequeños)","1/2 taza de salsa de tomate (kétchup)","3 dientes de ajo (picados)","1 cucharada de chile en polvo","2 cucharaditas de comino molido","1 cucharadita de orégano seco","1/2 cucharadita de sal","1/4 de cucharadita de pimienta negra"],
["Precaliente el horno a 350° F. Rocíe un molde para pan de 9 × 5 pulgadas con aceite en aerosol antiadherente.","Agregue todos los demás ingredientes a un tazón grande. Mezcle con suavidad los ingredientes hasta que estén bien integrados.","Con una cuchara, pase la mezcla al molde para pan preparado y empareje la parte superior con el dorso de la cuchara o una espátula. Coloque el molde en el horno y hornee hasta que un termómetro insertado en el centro del pastel de carne marque 165° F, 1 hora."],[],[]),
ar=("رغيف لحم الديك الرومي على الطريقة الجنوبية الغربية","من الطرق الجيدة لإضافة الحبوب الكاملة إلى أطباق البروتين، مثل رغيف اللحم والهامبرغر وكرات اللحم، استخدام الشوفان سريع الطهي بدلًا من فتات الخبز المعتاد. وقد ثبت أن الألياف الموجودة في الشوفان تساعد على خفض الكوليسترول. أكمل طبقك: لوجبة كلاسيكية من \"اللحم والبطاطس\"، قدّمه مع هريس البطاطس الحمراء. وأضف سلطة خضراء بالبرتقال والأفوكادو لوجبة متوازنة.","8","1 شريحة",
["1 بخّة (0.25 غرام) بخاخ طهي غير لاصق","1½ رطل لحم ديك رومي مفروم خالٍ من الدهون","1 كوب شوفان سريع الطهي","1 حبة بصل أصفر كبيرة (مفرومة ناعمًا)","2 بيضة كبيرة (مخفوقة)","1 حبة فلفل رومي أخضر متوسطة (مقطعة إلى مكعبات صغيرة)","½ كوب كاتشب","3 فص ثوم (مفروم)","1 ملعقة كبيرة مسحوق الفلفل الحار","2 ملعقة صغيرة كمون مطحون","1 ملعقة صغيرة أوريغانو مجفف","½ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود"],
["سخّن الفرن مسبقًا إلى 350° فهرنهايت (175° مئوية). ادهن قالب رغيف مقاس 9 × 5 بوصات ببخاخ الطهي غير اللاصق.","ضع جميع المكونات المتبقية في وعاء كبير. اخلط المكونات برفق حتى تمتزج جيدًا.","اغرف الخليط في قالب الرغيف المجهّز، واستخدم ظهر الملعقة أو السباتولا لتسوية الوجه. ضع القالب في الفرن واخبز حتى يشير الترمومتر المغروس في وسط رغيف اللحم إلى 165° فهرنهايت (75° مئوية)، لمدة ساعة واحدة."],[],[])))
O.append(R(6558356,
es=("Manzanas con miel de maple","Saltear las manzanas carameliza sus azúcares naturales y crea un sabor intenso y dulce. Estas manzanas se mezclan con un almíbar bajo en azúcar hecho de sidra de manzana y sirope de maple sin azúcar para obtener un postre delicioso apto para personas con diabetes. O sírvalas sobre yogur griego natural para un desayuno dulce pero saciante.","4","1/2 manzana",
["2 manzanas medianas Granny Smith u otra manzana ácida (sin pelar y cortadas en gajos de 1/2 pulgada)","1 cucharada de jugo de limón","1 cucharadita de aceite de canola","1/4 de taza de sidra de manzana","1 cucharada de sirope tipo maple sin azúcar","1/4 de cucharadita de clavo molido","1/4 de cucharadita de canela molida","1 cucharada de almendras en láminas (tostadas)"],
["Mezcle las rodajas de manzana con el jugo de limón.","En una sartén grande, caliente el aceite a fuego medio. Agregue las manzanas y saltee durante 3 minutos. Reduzca el fuego a bajo, tape y cocine a fuego lento unos 6 a 7 minutos, revolviendo de vez en cuando. Retire las manzanas de la sartén y reserve.","En la misma sartén, agregue todos los demás ingredientes, excepto las almendras. Lleve a ebullición y cocine a fuego medio-alto hasta que tome consistencia de almíbar, raspando los trocitos de manzana que queden en la sartén. Vuelva a agregar las manzanas y espolvoree con las almendras en láminas."],[],[]),
ar=("تفاح بشراب القيقب","يؤدي تسويط التفاح إلى كرملة سكرياته الطبيعية مما يمنحه نكهة غنية وحلوة. يُقلَّب هذا التفاح في شراب قليل السكر محضّر من عصير التفاح وشراب القيقب الخالي من السكر للحصول على حلوى لذيذة مناسبة لمرضى السكري. أو قدّمه فوق الزبادي اليوناني السادة لفطور حلو لكنه مشبع.","4","½ تفاحة",
["2 حبة تفاح متوسطة من نوع غراني سميث أو أي تفاح حامض آخر (غير مقشرة ومقطعة إلى أسافين بسمك ½ بوصة)","1 ملعقة كبيرة عصير ليمون","1 ملعقة صغيرة زيت الكانولا","¼ كوب عصير تفاح (سايدر)","1 ملعقة كبيرة شراب بنكهة القيقب خالٍ من السكر","¼ ملعقة صغيرة قرنفل مطحون","¼ ملعقة صغيرة قرفة مطحونة","1 ملعقة كبيرة لوز شرائح (محمص)"],
["قلّب شرائح التفاح مع عصير الليمون.","في مقلاة كبيرة، سخّن الزيت على حرارة متوسطة. أضف التفاح وسوّطه لمدة 3 دقائق. اخفض الحرارة إلى منخفضة، وغطِّ المقلاة واتركه على نار هادئة لمدة 6 إلى 7 دقائق تقريبًا مع التحريك من حين لآخر. أخرج التفاح من المقلاة واتركه جانبًا.","في المقلاة نفسها، أضف جميع المكونات المتبقية باستثناء اللوز. اتركها حتى تغلي واطهِ على حرارة متوسطة عالية حتى تصبح بقوام الشراب، مع كشط أي قطع تفاح متبقية في المقلاة. أعد التفاح إلى المقلاة ورشّ فوقه شرائح اللوز."],[],[])))
